const source = $('Ler Fontes Ativas').item.json;
const html = $json.data || '';
const metodo = source.metodo || 'html_json_ld';
const siteOrigem = source.nome || '';
const regiao = source.regiao || '';
const agora = new Date().toISOString();

function hashStr(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(31, h) + str.charCodeAt(i) | 0;
  }
  return Math.abs(h).toString(16).padStart(8, '0');
}

function toNum(val) {
  if (!val) return 0;
  return parseFloat(String(val).replace(/[R$\s.]/g, '').replace(',', '.')) || 0;
}

let raw = [];

if (metodo === 'json_embutido') {
  const m = html.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/);
  if (m) {
    try {
      const d = JSON.parse(m[1]);
      const ads = d?.props?.pageProps?.ads || d?.props?.pageProps?.listingProps?.adList || [];
      raw = ads.map(a => {
        const item = {};
        item.titulo = a.subject || '';
        item.preco_raw = toNum(a.priceValue);
        item.bairro = a.location?.neighbourhood || a.location?.zone || regiao;
        item.link = a.url || a.friendlyUrl || '';
        item.imagem = a.images?.[0]?.originalImage || '';
        item.descricao = a.body || '';
        item.data_anuncio = a.listTime ? new Date(a.listTime * 1000).toISOString() : '';
        item.quartos = parseInt(a.rooms) || 0;
        item.metragem = parseFloat(a.size) || 0;
        item.banheiros = 0;
        item.endereco = '';
        return item;
      });
    } catch(e) {}
  }
} else if (metodo !== 'playwright') {
  const re = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    try {
      const d = JSON.parse(m[1]);
      const items = [];
      if (Array.isArray(d)) items.push(...d);
      else if (d.itemListElement) items.push(...d.itemListElement.map(i => i.item || i));
      else items.push(d);
      for (const el of items) {
        if (!el || !el['@type']) continue;
        const t = String(el['@type']);
        if (!t.includes('RealEstate') && t !== 'Product' && !t.includes('Apartment') && !t.includes('House')) continue;
        const entry = {};
        entry.titulo = el.name || '';
        entry.preco_raw = toNum(el.offers?.price || el.price || '');
        entry.bairro = el.address?.addressLocality || regiao;
        entry.link = el.url || el.offers?.url || '';
        entry.imagem = Array.isArray(el.image) ? (el.image[0] || '') : (el.image || '');
        entry.descricao = el.description || '';
        entry.data_anuncio = '';
        entry.quartos = parseInt(el.numberOfBedrooms || '0') || 0;
        entry.banheiros = parseInt(el.numberOfFullBathrooms || el.numberOfBathrooms || '0') || 0;
        entry.metragem = parseFloat(String(el.floorSize?.value || el.floorSize || '0')) || 0;
        entry.endereco = el.address?.streetAddress || '';
        raw.push(entry);
      }
    } catch(e) {}
  }
}

return raw
  .filter(l => l.link && l.titulo)
  .map(l => {
    const preco = l.preco_raw || 0;
    const desc = (l.titulo + ' ' + l.descricao).toLowerCase();
    const vaga = desc.includes('vaga') || desc.includes('garagem');
    const mobiliado = desc.includes('mobiliado') || desc.includes('mobiliada');
    const tags = [];
    if (preco > 0 && preco <= 1500) tags.push('abaixo_orcamento');
    if (preco <= 1800) tags.push('total_ate_1800');
    if (vaga) tags.push('vaga');
    if (mobiliado) tags.push('mobiliado');
    if (preco > 0 && preco <= 1500 && vaga) tags.push('boa_oportunidade');
    tags.push('anuncio_novo');
    const out = {};
    out.hash = hashStr(l.link.split('?')[0].split('#')[0]);
    out.titulo = l.titulo.substring(0, 200);
    out.preco_aluguel = preco;
    out.condominio = 0;
    out.total_estimado = preco;
    out.bairro = l.bairro || regiao;
    out.regiao = regiao;
    out.endereco = l.endereco || '';
    out.quartos = l.quartos || 0;
    out.banheiros = l.banheiros || 0;
    out.metragem = l.metragem || 0;
    out.vaga = vaga ? 'TRUE' : 'FALSE';
    out.descricao = (l.descricao || '').substring(0, 500);
    out.link = l.link;
    out.imagem_principal = l.imagem || '';
    out.anunciante = '';
    out.telefone = '';
    out.whatsapp = '';
    out.site_origem = siteOrigem;
    out.data_coleta = agora;
    out.data_anuncio = l.data_anuncio || '';
    out.data_atualizacao = agora;
    out.tags = tags.join(',');
    out.status = 'novo';
    out.destaque = 'FALSE';
    return { json: out };
  });
